#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const DEFAULT_INPUT_FILES = Object.freeze([
    path.join('public', 'js', 'gameVariantRegistry.js'),
    path.join('public', 'js', 'gameHubViewCore.js'),
    path.join('public', 'js', 'gameHubProfileView.js'),
    path.join('public', 'js', 'gameHubDuelRoomView.js'),
    path.join('public', 'js', 'gameHubCardsView.js'),
    path.join('public', 'js', 'gameHubDashboardView.js'),
    path.join('public', 'js', 'gameHubController.js')
]);
const DEFAULT_OUTPUT_FILE = path.join('public', 'game-hub.bundle.js');
const GENERATED_HEADER = '/*! F1 Guesser Duel | generated by scripts/build-game-hub-bundle.js; edit public/js/gameHub*.js sources */';

function normalizeLineEndings(content) {
    return String(content || '').replace(/\r\n?/g, '\n');
}

function normalizePathForOutput(inputPath) {
    return String(inputPath || '').replace(/\\/g, '/');
}

function buildGameHubBundle(rootDir = process.cwd(), options = {}) {
    const inputFiles = options.inputFiles || DEFAULT_INPUT_FILES;
    const outputFile = options.outputFile || DEFAULT_OUTPUT_FILE;
    const normalizedInputs = inputFiles.map(normalizePathForOutput);
    const sections = [];
    let sourceBytes = 0;

    for (const inputFile of inputFiles) {
        const absolutePath = path.join(rootDir, inputFile);
        if (!fs.existsSync(absolutePath)) {
            throw new Error(`Game Hub source file not found: ${normalizePathForOutput(inputFile)}`);
        }

        const source = normalizeLineEndings(fs.readFileSync(absolutePath, 'utf8')).trimEnd();
        sourceBytes += Buffer.byteLength(source, 'utf8');
        sections.push(source);
    }

    const bundleContent = `${GENERATED_HEADER}\n${sections.join('\n;\n')}\n`;
    const outputPath = path.join(rootDir, outputFile);
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, bundleContent, 'utf8');

    const bundle = Buffer.from(bundleContent, 'utf8');
    return {
        inputFiles: normalizedInputs,
        inputCount: normalizedInputs.length,
        outputFile: normalizePathForOutput(outputFile),
        sourceBytes,
        bundleBytes: bundle.length,
        gzipBytes: zlib.gzipSync(bundle, { level: zlib.constants.Z_BEST_COMPRESSION }).length,
        brotliBytes: zlib.brotliCompressSync(bundle, {
            params: {
                [zlib.constants.BROTLI_PARAM_QUALITY]: 11
            }
        }).length
    };
}

function runCli() {
    const result = buildGameHubBundle(process.cwd());
    console.log(`Bundle Game Hub creat: ${result.outputFile}`);
    console.log(`Module incluse: ${result.inputCount}`);
    console.log(`Bundle: ${(result.bundleBytes / 1024).toFixed(2)} KB`);
    console.log(`Bundle gzip: ${(result.gzipBytes / 1024).toFixed(2)} KB`);
    console.log(`Bundle Brotli: ${(result.brotliBytes / 1024).toFixed(2)} KB`);
}

if (require.main === module) {
    try {
        runCli();
    } catch (error) {
        console.error(`Eroare build Game Hub: ${error.message}`);
        process.exitCode = 1;
    }
}

module.exports = {
    DEFAULT_INPUT_FILES,
    DEFAULT_OUTPUT_FILE,
    GENERATED_HEADER,
    buildGameHubBundle,
    normalizeLineEndings,
    normalizePathForOutput
};
